namespace Warehouse;

public sealed class InventoryTracker
{
    private const int DefaultReorderThreshold = 5;
    private readonly Dictionary<string, int> _stock = new();
    private readonly Dictionary<string, int> _thresholds = new();

    public int GetStockLevel(string sku)
    {
        ValidateSku(sku);
        return _stock.TryGetValue(sku, out var level) ? level : 0;
    }

    public void AddStock(string sku, int quantity)
    {
        ValidateSku(sku);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be greater than zero.");

        _stock[sku] = GetStockLevel(sku) + quantity;
    }

    public void RemoveStock(string sku, int quantity)
    {
        ValidateSku(sku);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be greater than zero.");

        var current = GetStockLevel(sku);
        if (current < quantity)
            throw new InvalidOperationException($"Insufficient stock for SKU '{sku}'. Available: {current}, requested: {quantity}.");

        _stock[sku] = current - quantity;
    }

    public bool NeedsReorder(string sku)
    {
        ValidateSku(sku);
        var level = GetStockLevel(sku);
        var threshold = _thresholds.TryGetValue(sku, out var t) ? t : DefaultReorderThreshold;
        return level <= threshold;
    }

    public void SetReorderThreshold(string sku, int threshold)
    {
        ValidateSku(sku);
        if (threshold < 0)
            throw new ArgumentOutOfRangeException(nameof(threshold), "Threshold must be non-negative.");

        _thresholds[sku] = threshold;
    }

    public void TransferTo(InventoryTracker destination, string sku, int quantity)
    {
        ArgumentNullException.ThrowIfNull(destination);
        ValidateSku(sku);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be greater than zero.");

        var current = GetStockLevel(sku);
        if (current < quantity)
            throw new InvalidOperationException($"Insufficient stock for SKU '{sku}'. Available: {current}, requested: {quantity}.");

        _stock[sku] = current - quantity;
        destination.AddStock(sku, quantity);
    }

    private static void ValidateSku(string sku)
    {
        if (string.IsNullOrEmpty(sku))
            throw new ArgumentException("SKU cannot be null or empty.", nameof(sku));
    }
}

using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    // ── Stock management ───────────────────────────────────────────

    [TestMethod]
    public void AddStock_NewSku_SetsLevel()
    {
        _tracker.AddStock("SKU-1", 10);
        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_Accumulates()
    {
        _tracker.AddStock("SKU-1", 10);
        _tracker.AddStock("SKU-1", 5);
        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN"));
    }

    [TestMethod]
    public void RemoveStock_DecrementsCorrectly()
    {
        _tracker.AddStock("SKU-1", 10);
        _tracker.RemoveStock("SKU-1", 3);
        Assert.AreEqual(7, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_InsufficientStock_ThrowsInvalidOperation()
    {
        _tracker.AddStock("SKU-1", 2);
        Assert.ThrowsException<InvalidOperationException>(() => _tracker.RemoveStock("SKU-1", 5));
    }

    [TestMethod]
    public void AddStock_NullSku_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.AddStock(null!, 1));
    }

    [TestMethod]
    public void AddStock_EmptySku_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.AddStock("", 1));
    }

    [TestMethod]
    public void AddStock_ZeroQuantity_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _tracker.AddStock("SKU-1", 0));
    }

    [TestMethod]
    public void AddStock_NegativeQuantity_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _tracker.AddStock("SKU-1", -1));
    }

    [TestMethod]
    public void RemoveStock_NullSku_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.RemoveStock(null!, 1));
    }

    [TestMethod]
    public void RemoveStock_ZeroQuantity_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _tracker.RemoveStock("SKU-1", 0));
    }

    [TestMethod]
    public void GetStockLevel_NullSku_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.GetStockLevel(null!));
    }

    // ── Reorder alerts ─────────────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_StockAtDefaultThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-1", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockBelowDefaultThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-1", 3);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveDefaultThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-1", 10);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_CustomThreshold_Works()
    {
        _tracker.SetReorderThreshold("SKU-1", 20);
        _tracker.AddStock("SKU-1", 15);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));

        _tracker.AddStock("SKU-1", 10);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("UNKNOWN"));
    }

    [TestMethod]
    public void SetReorderThreshold_NegativeValue_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _tracker.SetReorderThreshold("SKU-1", -1));
    }

    [TestMethod]
    public void NeedsReorder_NullSku_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.NeedsReorder(null!));
    }

    [TestMethod]
    public void SetReorderThreshold_NullSku_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.SetReorderThreshold(null!, 5));
    }

    // ── Warehouse transfers ────────────────────────────────────────

    [TestMethod]
    public void TransferTo_MovesStockCorrectly()
    {
        var dest = new InventoryTracker();
        _tracker.AddStock("SKU-1", 20);

        _tracker.TransferTo(dest, "SKU-1", 8);

        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-1"));
        Assert.AreEqual(8, dest.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void TransferTo_InsufficientStock_ThrowsInvalidOperation()
    {
        var dest = new InventoryTracker();
        _tracker.AddStock("SKU-1", 3);
        Assert.ThrowsException<InvalidOperationException>(() => _tracker.TransferTo(dest, "SKU-1", 10));
    }

    [TestMethod]
    public void TransferTo_NullDestination_ThrowsArgumentNullException()
    {
        _tracker.AddStock("SKU-1", 5);
        Assert.ThrowsException<ArgumentNullException>(() => _tracker.TransferTo(null!, "SKU-1", 1));
    }

    [TestMethod]
    public void TransferTo_InvalidSku_ThrowsArgumentException()
    {
        var dest = new InventoryTracker();
        Assert.ThrowsException<ArgumentException>(() => _tracker.TransferTo(dest, "", 1));
    }

    [TestMethod]
    public void TransferTo_InvalidQuantity_ThrowsArgumentOutOfRange()
    {
        var dest = new InventoryTracker();
        _tracker.AddStock("SKU-1", 10);
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _tracker.TransferTo(dest, "SKU-1", 0));
    }
}

