     {
         ValidateSku(sku);
         if (quantity <= 0)
             throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be greater than zero.");

         _stock[sku] = GetStockLevel(sku) + quantity;
     }

     public void RemoveStock(string sku, int quantity)
     {
         ValidateSku(sku);
         if (quantity <= 0)
             throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be greater than zero.");

         var current = GetStockLevel(sku);
         if (current < quantity)
             throw new InvalidOperationException($"Insufficient stock for SKU '{sku}'. Available: {current}, requested: {quantity}.");

         _stock[sku] = current - quantity;
     }

     public bool NeedsReorder(string sku)
     {
         ValidateSku(sku);
         var level = GetStockLevel(sku);
         var threshold = _thresholds.TryGetValue(sku, out var t) ? t : DefaultReorderThreshold;
         return level <= threshold;
     }

     public void SetReorderThreshold(string sku, int threshold)
     {
         ValidateSku(sku);
         if (threshold < 0)
             throw new ArgumentOutOfRangeException(nameof(threshold), "Threshold must be non-negative.");

         _thresholds[sku] = threshold;
     }

     public void TransferTo(InventoryTracker destination, string sku, int quantity)
     {
         ArgumentNullException.ThrowIfNull(destination);
         ValidateSku(sku);
         if (quantity <= 0)
             throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be greater than zero.");

         var current = GetStockLevel(sku);
         if (current < quantity)
             throw new InvalidOperationException($"Insufficient stock for SKU '{sku}'. Available: {current}, requested: {quantity}.");

         _stock[sku] = current - quantity;
         destination.AddStock(sku, quantity);
     }

     private static void ValidateSku(string sku)
     {
         if (string.IsNullOrEmpty(sku))
             throw new ArgumentException("SKU cannot be null or empty.", nameof(sku));
     }
 }

